{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Aprepitant, a high-transfer analogue, has absolute oral bioavailability of 65% (95% CI 57-75%) in fasted men, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Silodosin has absolute oral bioavailability of 32.2% in healthy men under fasted conditions, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Bepotastine is reported to have high oral bioavailability/absorption greater than 80% in humans, strongly above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Lemborexant is at least 87% bioavailable in healthy subjects based on mass-balance data, well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alizapride has an absolute oral availability of 72.5% versus intravenous administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Basmisanil has an absolute oral bioavailability of approximately 75% in humans, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Setipiprant bioavailability in humans is at least 50%, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Encainide in normal subjects has a mean oral bioavailability of 30 ± 7%, above 20% despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Haloperidol has a mean absolute oral bioavailability of 35% (range 21-44%) in patients, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "LY2196044 has an estimated absolute oral bioavailability of 45% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer human absolute oral bioavailability data for structurally related analogues are above the 20% threshold, with reported values ranging from about 30% to >87%; no affirmative evidence supports F < 20%, so the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "Some analogues (encainide, haloperidol) show variable bioavailability due to first-pass metabolism, but all reported means remain above 20%.",
    "The physicochemical prior is mixed/unclear and does not provide affirmative evidence for low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

